+
+      .intro {
+        margin: 0 0 1.5rem;
+        color: var(--muted);
+      }
+
+      .form-field {
+        margin-bottom: 1.25rem;
+      }
+
+      .checkbox-row {
+        display: flex;
+        align-items: flex-start;
+        gap: 0.85rem;
+      }
+
+      input[type="checkbox"] {
+        width: 1.15rem;
+        height: 1.15rem;
+        margin: 0.2rem 0 0;
+        accent-color: var(--accent-strong);
+        flex: none;
+      }
+
+      label {
+        font-weight: 600;
+      }
+
+      .required {
+        color: #fbbf24;
+      }
+
+      .helper-text,
+      .error-text,
+      .status-text {
+        margin: 0.65rem 0 0;
+        font-size: 0.95rem;
+      }
+
+      .helper-text {
+        color: var(--muted);
+      }
+
+      .error-text {
+        color: var(--danger);
+      }
+
+      .status-text {
+        color: var(--success);
+        min-height: 1.5rem;
+      }
+
+      button {
+        width: 100%;
+        border: 0;
+        border-radius: 0.9rem;
+        padding: 0.95rem 1.1rem;
+        font: inherit;
+        font-weight: 700;
+        color: #03111f;
+        background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
+        cursor: pointer;
+        transition: transform 120ms ease, box-shadow 120ms ease, filter 120ms ease;
+        box-shadow: 0 14px 30px rgba(56, 189, 248, 0.22);
+      }
+
+      button:hover {
+        filter: brightness(1.05);
+        transform: translateY(-1px);
+      }
+
+      button:active {
+        transform: translateY(0);
+      }
+
+      a {
+        color: #bae6fd;
+      }
+
+      a:hover {
+        color: #e0f2fe;
+      }
+
+      input:focus-visible,
+      button:focus-visible,
+      a:focus-visible {
+        outline: 3px solid var(--accent);
+        outline-offset: 3px;
+      }
+
+      @media (max-width: 480px) {
+        .card {
+          padding: 1.25rem;
+        }
+
+        .checkbox-row {
+          gap: 0.7rem;
+        }
+      }
+
+      @media (forced-colors: active) {
+        .card,
+        button,
+        .skip-link {
+          border: 1px solid CanvasText;
+          box-shadow: none;
+        }
+
+        button {
+          background: ButtonFace;
+          color: ButtonText;
+        }
+
+        .error-text,
+        .helper-text,
+        .status-text {
+          color: CanvasText;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <main id="main-content">
+      <section class="card" aria-labelledby="form-title">
+        <h1 id="form-title">Confirm your consent</h1>
+        <p class="intro">Agree to the terms of use before sending your confirmation.</p>
+
+        <form id="consent-form" action="#" method="post" novalidate>
+          <div class="form-field">
+            <div class="checkbox-row">
+              <input
+                id="consent"
+                name="consent"
+                type="checkbox"
+                required
+                aria-describedby="consent-help"
+              >
+              <label for="consent">
+                I agree to the <a href="#" aria-label="terms of use">terms of use</a>
+                <span class="required" aria-hidden="true">*</span>
+              </label>
