        margin: 0 0 0.75rem;
        font-size: clamp(1.7rem, 4vw, 2.2rem);
        line-height: 1.15;
      }

      .intro {
        margin: 0 0 1.5rem;
        color: var(--muted);
      }

      .form-field {
        margin-bottom: 1.25rem;
      }

      .checkbox-row {
        display: flex;
        align-items: flex-start;
        gap: 0.85rem;
