              >
              <label for="consent">
                I agree to the <a href="#" aria-label="terms of use">terms of use</a>
                <span class="required" aria-hidden="true">*</span>
              </label>
            </div>
            <p id="consent-help" class="helper-text">Required to continue.</p>
            <p id="consent-error" class="error-text" hidden>Error: You must agree before submitting.</p>
          </div>

          <button type="submit">Submit consent</button>
          <p id="form-status" class="status-text" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("consent-form");
      const consent = document.getElementById("consent");
      const error = document.getElementById("consent-error");
      const status = document.getElementById("form-status");

      function showError() {
        error.hidden = false;
        consent.setAttribute("aria-invalid", "true");
        consent.setAttribute("aria-describedby", "consent-help consent-error");
      }

      function clearError() {
        error.hidden = true;
        consent.removeAttribute("aria-invalid");
        consent.setAttribute("aria-describedby", "consent-help");
      }

      form.addEventListener("submit", (event) => {
