     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <section class="card" aria-labelledby="form-title">
         <h1 id="form-title">Confirm your consent</h1>
         <p class="intro">Agree to the terms of use before sending your confirmation.</p>

         <form id="consent-form" action="#" method="post" novalidate>
           <div class="form-field">
             <div class="checkbox-row">
               <input
                 id="consent"
                 name="consent"
                 type="checkbox"
                 required
                 aria-describedby="consent-help"
               >
               <label for="consent">
                 I agree to the terms of use <span class="required" aria-hidden="true">*</span>
               </label>
             </div>
             <p id="consent-help" class="helper-text">Required to continue.</p>
             <p id="consent-error" class="error-text" hidden>Error: You must agree before submitting.</p>
           </div>

           <button type="submit">Submit consent</button>
           <p id="form-status" class="status-text" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById("consent-form");
       const consent = document.getElementById("consent");
       const error = document.getElementById("consent-error");
       const status = document.getElementById("form-status");

       function showError() {
         error.hidden = false;
         consent.setAttribute("aria-invalid", "true");
         consent.setAttribute("aria-describedby", "consent-help consent-error");
       }

       function clearError() {
         error.hidden = true;
         consent.removeAttribute("aria-invalid");
         consent.setAttribute("aria-describedby", "consent-help");
       }

       form.addEventListener("submit", (event) => {
         status.textContent = "";

         if (!consent.checked) {
           event.preventDefault();
           showError();
           consent.focus();
           return;
         }

         event.preventDefault();
         clearError();
         status.textContent = "Consent submitted successfully.";
       });

       consent.addEventListener("change", () => {
         if (consent.checked) {
           clearError();
           return;
         }

         status.textContent = "";
       });
     </script>
   </body>
 </html>

